import { readFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { describe, expect, it } from 'vitest';
const { Parser } = createRequire(import.meta.url)('@pgsql/parser');
const sqlPath = 'supabase/migrations/20261025035331_operation_atomic_audit_admission.sql';
const text = path => readFileSync(path, 'utf8').replaceAll('\r\n', '\n');

describe('finite atomic audit source contract', () => {
  it('keeps the Node authority and generated Edge copy identical', () => {
    expect(text('supabase/functions/_shared/operation-atomic-rpc.ts')).toBe(
      '// Generated by scripts/generate-operation-atomic-edge.mjs. DO NOT EDIT.\n' +
      text('src/modules/developer-reset/operation-atomic-rpc.ts'));
  });
  it.each([15, 17])('parses the migration and prepared regression with PG%s grammar only', async version => {
    const parser = new Parser({ version });
    for (const path of [sqlPath, 'supabase/tests/operation_atomic_audit_admission.sql']) {
      expect(await parser.parse(text(path))).toBeTruthy();
    }
  });
  it('keeps the finite authority service-only and original effects inside the locked admission transaction', () => {
    const sql = text(sqlPath);
    expect(sql).not.toMatch(/\bexecute\s+format\s*\(/i);
    expect(sql).toContain('where singleton for update');
    for (const rpc of ['record_actor_activity_event', 'record_unknown_login_failure', 'record_authorization_denial', 'mark_notification_read']) {
      expect(sql).toContain(`when '${rpc}' then`);
      expect(sql).toContain(`public.${rpc}(`);
    }
    expect(sql).toContain('private.acquire_developer_operation_admission');
    expect(sql).toContain('private.complete_developer_operation_admission');
    expect(sql).toMatch(/revoke all[^;]+from public,anon,authenticated,service_role;/);
    expect(sql).toMatch(/grant execute[^;]+to service_role;/);
  });
});
